-- Manually generated
local InternetGatewayDevice_X_Management_Server_SSHServer_ = {
  objectType = {
    name = "InternetGatewayDevice.X_Management.Server.SSHServer.",
    access = "readOnly",
    description = "SSH Service Parameters",
    minEntries = 1,
    maxEntries = 1,
    parameters = {
      Enable = {
        access = "readWrite",
        type = "boolean",
        description = "Enables/Disables SSH service on the gateway",
      },
    },
  }
}

local dropBearBinding = { config = "dropbear", sectionname = "dropbear" }
local configChanged

InternetGatewayDevice_X_Management_Server_SSHServer_.get = {
  Enable = function()
    local value = "0"
    foreachOnUci(dropBearBinding, function(s)
      if s.enable == "1" then
        value = "1"
        return false
      end
    end)
    return value
  end
}

InternetGatewayDevice_X_Management_Server_SSHServer_.set = {
  Enable = function(mapping, param, value)
    local binding = { config = "dropbear" }
    foreachOnUci(dropBearBinding, function(s)
      binding.sectionname = s[".name"]
      binding.option = "enable"
      setOnUci(binding, value, commitapply)
      configChanged = true
    end)
  end
}

InternetGatewayDevice_X_Management_Server_SSHServer_.commit = function()
  if configChanged then
    commit(dropBearBinding)
  end
  configChanged = false
end

InternetGatewayDevice_X_Management_Server_SSHServer_.revert = function()
  if configChanged then
    revert(dropBearBinding)
  end
  configChanged = false
end

register(InternetGatewayDevice_X_Management_Server_SSHServer_)
